const prefixo = 'grupo3/iluminacao/';
if (msg.topic === prefixo + 'status') {
    if (msg.payload === 'online' || msg.payload === 'offline') {
        flow.set('placaOnline', msg.payload === 'online');
        if (msg.payload === 'offline') flow.set('telemetriaAtual', null);
    }
    return;
}

const dado = msg.payload;
const modos = ['automatico', 'ligada', 'desligada'];
if (!dado || !Number.isInteger(dado.ldr) || dado.ldr < 0 || dado.ldr > 4095 ||
    typeof dado.luz !== 'boolean' || !modos.includes(dado.modo)) {
    return;
}

const simulado = dado.simulado === true;
const estado = { ldr: dado.ldr, luz: dado.luz, modo: dado.modo, simulado, recebidoEm: Date.now() };
flow.set('telemetriaAtual', estado);

const historico = flow.get('historico') || [];
const anterior = historico[0];
if (!anterior || anterior.ldr !== estado.ldr || anterior.luz !== estado.luz || anterior.modo !== estado.modo || anterior.simulado !== simulado) {
    flow.set('historico', [estado, ...historico].slice(0, 20));
}

if (typeof dado.confirmacao === 'string' && /^[0-9a-f]{1,32}$/.test(dado.confirmacao)) {
    const confirmacoes = flow.get('confirmacoes') || [];
    flow.set('confirmacoes', [{ id: dado.confirmacao, modo: estado.modo, simulado }, ...confirmacoes].slice(0, 20));
}

const conectado = msg.status.fill === 'green';
flow.set('brokerOnline', conectado);
if (!conectado) {
    flow.set('placaOnline', false);
    flow.set('telemetriaAtual', null);
}

const estado = flow.get('telemetriaAtual');
const brokerOnline = flow.get('brokerOnline') === true;
const placaOnline = flow.get('placaOnline') === true;
msg.headers = { 'Cache-Control': 'no-store' };
msg.payload = {
    conexao: !brokerOnline || !placaOnline ? 'offline' :
        !estado || Date.now() - estado.recebidoEm > 7000 ? 'desatualizada' : 'online',
    estado: estado || null,
    historico: flow.get('historico') || [],
    confirmacoes: flow.get('confirmacoes') || []
};
return msg;

msg.headers = { 'Cache-Control': 'no-store' };
const tipo = msg.req.headers['content-type']?.split(';')[0].trim().toLowerCase();
if (tipo !== 'application/json') {
    msg.statusCode = 415;
    msg.payload = { erro: 'Envie um comando em JSON.' };
    return [null, msg];
}

const modo = msg.payload?.modo;
if (!['automatico', 'ligada', 'desligada'].includes(modo)) {
    msg.statusCode = 400;
    msg.payload = { erro: 'Modo inválido.' };
    return [null, msg];
}

const estado = flow.get('telemetriaAtual');
if (!flow.get('brokerOnline') || !flow.get('placaOnline') || !estado ||
    Date.now() - estado.recebidoEm > 7000) {
    msg.statusCode = 503;
    msg.payload = { erro: 'ESP32 indisponível. Aguarde a reconexão.' };
    return [null, msg];
}

const id = msg._msgid;
msg.statusCode = 202;
msg.payload = { id };
return [{
    topic: 'grupo3/iluminacao/comando',
    payload: JSON.stringify({ modo, id })
}, msg];
